# Preserve launcher lifetime on Stop and game exit.
lifecycle = json.loads("[[\"HWND g_control{},g_targets{},g_multi{},g_start{},g_stop{},g_overlay{},g_dynamicTarget{};\",\"HWND g_control{},g_targets{},g_multi{},g_start{},g_stop{},g_dynamicTarget{};\\nstd::atomic<HWND> g_overlay{nullptr};\"],[\"std::vector<Game> g_games;\",\"std::vector<Game> g_games;\\nstd::optional<Game> g_activeGame; // launcher thread only\"],[\"        if(tracked.Exited())return SessionOutcome::Stop;\",\"        if(tracked.Exited() || g_userStopRequested.load(std::memory_order_acquire))return SessionOutcome::Stop;\"],[\"while(g_running.load(std::memory_order_acquire)){\",\"while(g_running.load(std::memory_order_acquire) && !g_userStopRequested.load(std::memory_order_acquire)){\"],[\"            overlay.SetVisible(focused);\",\"            if(g_userStopRequested.load(std::memory_order_acquire) || tracked.Exited())break;\\n            overlay.SetVisible(focused);\"],[\"        g_running.store(true,std::memory_order_release);\\n        const SessionOutcome outcome\",\"        g_running.store(true,std::memory_order_release);\\n        if(g_userStopRequested.load(std::memory_order_acquire))break;\\n        const SessionOutcome outcome\"],[\"LRESULT CALLBACK ControlProc(HWND hwnd,UINT msg,WPARAM wp,LPARAM lp){\",\"// Stop is a launcher action, not a window-close action. The worker owns GPU teardown.\\nvoid RequestSessionStop(HWND hwnd){\\n    if(g_engineFinished.load(std::memory_order_acquire))return;\\n    g_userStopRequested.store(true,std::memory_order_release);\\n    g_running.store(false,std::memory_order_release);\\n    if(HWND overlay=g_overlay.load(std::memory_order_acquire))ShowWindowAsync(overlay,SW_HIDE);\\n    EnableWindow(g_stop,FALSE);\\n    SetWindowTextW(hwnd,L\\\"FG | Stopping...\\\");\\n}\\nvoid CompleteSessionUi(HWND hwnd){\\n    if(!g_engineFinished.load(std::memory_order_acquire))return;\\n    if(g_worker.joinable())g_worker.join();\\n    const bool exited=g_lastGameExited.exchange(false,std::memory_order_acq_rel);\\n    g_activeGame.reset();\\n    ReleaseRawMouse();\\n    EnableWindow(g_start,TRUE);\\n    EnableWindow(g_stop,FALSE);\\n    EnableWindow(g_reflex2,TRUE);\\n    SetWindowTextW(hwnd,L\\\"FG\\\");\\n    if(exited)RefreshGames();\\n}\\nLRESULT CALLBACK ControlProc(HWND hwnd,UINT msg,WPARAM wp,LPARAM lp){\"],[\"        if(wp==kLauncherLifecycleTimer &&\\n           g_engineFinished.load(std::memory_order_acquire) &&\\n           !IsWindowEnabled(g_start)){\\n            // Engine owns GPU teardown; only the GUI joins after completion.\\n            if(g_worker.joinable())g_worker.join();\\n            EnableWindow(g_start,TRUE);\\n            EnableWindow(g_stop,FALSE);\\n            EnableWindow(g_reflex2,TRUE);ReleaseRawMouse();\\n            if(g_lastGameExited.exchange(false,std::memory_order_acq_rel))RefreshGames();\\n        }\",\"        if(wp==kLauncherLifecycleTimer && !IsWindowEnabled(g_start)){\\n            if(g_engineFinished.load(std::memory_order_acquire))CompleteSessionUi(hwnd);\\n            else if(g_activeGame && !g_userStopRequested.load(std::memory_order_acquire)){\\n                DWORD pid=0;\\n                if(!IsWindow(g_activeGame->window) ||\\n                   !GetWindowThreadProcessId(g_activeGame->window,&pid) || pid!=g_activeGame->pid)\\n                    RequestSessionStop(hwnd);\\n            }\\n        }\"],[\"        if(wp==kEmergencyHotkey){\\n            g_userStopRequested.store(true);\\n            g_running.store(false);\\n        }\",\"        if(wp==kEmergencyHotkey)RequestSessionStop(hwnd);\"],[\"        case kRefresh:if(!g_running.load())RefreshGames();break;\",\"        case kRefresh:if(g_engineFinished.load(std::memory_order_acquire))RefreshGames();break;\"],[\"            g_worker=std::thread([game]{Engine(game);});\",\"            g_activeGame=game;\\n            try{g_worker=std::thread([game]{Engine(game);});}\\n            catch(const std::exception& e){g_running.store(false);g_engineFinished.store(true,std::memory_order_release);CompleteSessionUi(hwnd);MessageBoxW(hwnd,Wide(e.what()).c_str(),L\\\"FG error\\\",MB_OK|MB_ICONERROR);break;}\"],[\"        case kStop:\\n            g_userStopRequested.store(true);\\n            g_running.store(false);EnableWindow(g_stop,FALSE);break;\",\"        case kStop:RequestSessionStop(hwnd);break;\"],[\"        if(s.rfind(L\\\"Native NGX submitted:\\\",0)==0)\",\"        if(g_userStopRequested.load(std::memory_order_acquire) && !g_engineFinished.load(std::memory_order_acquire))return 0;\\n        if(s.rfind(L\\\"Native NGX submitted:\\\",0)==0)\"],[\"        if(!g_engineFinished.load(std::memory_order_acquire))return 0;\\n        if(g_worker.joinable())g_worker.join();\\n        EnableWindow(g_start,TRUE);EnableWindow(g_stop,FALSE);\\n        EnableWindow(g_reflex2,TRUE);ReleaseRawMouse();\\n        if(g_lastGameExited.exchange(false,std::memory_order_acq_rel))RefreshGames();\",\"        CompleteSessionUi(hwnd);\"]]")
p = root/'fg'/'src/main.cpp'
s = p.read_text(encoding='utf-8')
for old, new in lifecycle:
    expected = 2 if old == 'while(g_running.load(std::memory_order_acquire)){' else 1
    if s.count(old) != expected:
        raise RuntimeError(f'Lifecycle patch: expected {expected} matches for {old[:100]}')
    s = s.replace(old,new)
p.write_text(s,encoding='utf-8',newline='\n')
print('Stop/game-exit launcher lifecycle patch applied.')

