(root/'fg'/'src'/'fg.frag').write_text("#version 450\nlayout(set=0,binding=0,std430) readonly buffer Pixels { uint pixels[]; };\nlayout(push_constant) uniform P { uint sourceWidth; uint sourceHeight; uint outputWidth; uint outputHeight; } p;\nlayout(location=0) out vec4 color;\nvec4 readPixel(uvec2 xy){\n    uint v=pixels[xy.y*p.sourceWidth+xy.x];\n    return vec4(float((v>>16)&255u),float((v>>8)&255u),float(v&255u),255.0)/255.0;\n}\nvoid main(){\n    uvec2 src=uvec2(p.sourceWidth,p.sourceHeight);\n    uvec2 dst=uvec2(p.outputWidth,p.outputHeight);\n    if(all(equal(src,dst))){color=readPixel(uvec2(gl_FragCoord.xy));return;}\n    // Fullscreen stretch only here, after native-resolution extrapolation.\n    vec2 pos=clamp(gl_FragCoord.xy*vec2(src)/vec2(dst)-0.5,vec2(0),vec2(src)-1.0);\n    uvec2 a=uvec2(floor(pos)),b=min(a+uvec2(1),src-uvec2(1));\n    vec2 f=fract(pos);\n    color=mix(mix(readPixel(a),readPixel(uvec2(b.x,a.y)),f.x),\n              mix(readPixel(uvec2(a.x,b.y)),readPixel(b),f.x),f.y);\n}\n", encoding='utf-8',newline='\n')
with (root/'fg'/'README.md').open('a',encoding='utf-8') as f:
    f.write('\n## Native capture resolution\nCUDA output buffers, NvOFA and NGX geometry/warp use the exact dimensions reported by NvFBC. No fixed 1920x1080 processing target. The fullscreen Vulkan surface still follows Windows display dimensions; stretch is only at presentation when necessary. No display-mode changes. If capture reports 1920x1080 even with a lower game setting, FG cannot recover the pre-scaled game buffer. The title bar reports the actual captured dimensions.\n')
print('Native-resolution processing and final presentation scaling patch applied.')
